const item = $json;

const scenarioId = item.ID || item.id || "SEM-ID";
const card = item.card || item.body?.card || {};
const acceptanceCriteria = Array.isArray(item.acceptanceCriteria)
  ? item.acceptanceCriteria
  : Array.isArray(card.acceptanceCriteria)
    ? card.acceptanceCriteria
    : [];
const scenarios = Array.isArray(item.scenarios)
  ? item.scenarios
  : Array.isArray(card.scenarios)
    ? card.scenarios
    : [];
const moduleName = item["Módulo"] || item.modulo || card.module || "Geral";
const title = item["Título"] || item.titulo || card.title || scenarioId;
const objective = item.Objetivo || item.objetivo || item.businessGoal || card.businessGoal || "";
const pre = item["Pré-condição / Cenário"] || item.precondicao || item.qaNotes || card.qaNotes || "";
const steps = item.Passos || item.passos || "";
const expected = item["Resultado Esperado"] || item.resultado || acceptanceCriteria.join("\n") || "";
const category = (item.Categoria || item.categoria || card.source || "Funcional").toString();
const group = (item._group || item.grupo || item.Categoria || "Funcional").toString().trim();

const hasUsefulContext = [title, objective, pre, steps, expected, card.qaNotes, acceptanceCriteria.join(" "), scenarios.map(s => s.title || s.id).join(" ")].some(v => String(v || "").trim().length > 0);
const shouldUseAI = hasUsefulContext;

const acceptanceList = acceptanceCriteria.length > 0
  ? acceptanceCriteria.map((a, i) => (i + 1) + ". " + String(a)).join("\n")
  : "";

const scenarioSummary = scenarios.length > 0
  ? scenarios.map(s => "- " + (s.id || "") + " " + (s.title || "") + " " + (s.source ? "(" + s.source + ")" : "") + " " + (s.status ? "[" + s.status + "]" : "").trim()).join("\n")
  : "";

const fallbackGherkin = [
  "Feature: " + (title || scenarioId),
  "",
  "  @" + scenarioId + " @" + category,
  "  Scenario: " + (objective || title || scenarioId),
  "    Given the scenario " + scenarioId + " is available",
  "    When the user processes the functional requirements",
  "    Then the expected business outcome should be validated"
].join("\n");

const prompt = item.bddPrompt || (
  "You are a senior QA automation engineer.\n" +
  "Rewrite the scenario below into high-quality Gherkin BDD for automation.\n\n" +
  "Rules:\n" +
  "- write in English\n" +
  "- output only the .feature content\n" +
  "- do not copy the manual test literally\n" +
  "- normalize the wording for reusable automation steps\n" +
  "- keep the business intent from the original scenario\n" +
  "- use clear Feature and Scenario names\n" +
  "- use tags with the scenario ID and category\n" +
  "- prefer concise, automation-friendly Given/When/Then steps\n" +
  "- do not invent requirements that are not present\n" +
  "- if the title/objective are sparse, infer the behavior from businessGoal, qaNotes and acceptanceCriteria without inventing new rules\n\n" +
  "Scenario data:\n" +
  "ID: " + scenarioId + "\n" +
  "Module: " + moduleName + "\n" +
  "Category: " + category + "\n" +
  "Group: " + group + "\n" +
  "Title: " + title + "\n" +
  "Business Goal: " + objective + "\n" +
  "QA Notes: " + pre + "\n" +
  "Manual Steps: " + steps + "\n" +
  "Expected Result: " + expected + "\n" +
  "Acceptance Criteria:\n" +
  (acceptanceList || "- none provided") + "\n" +
  "Related Scenarios:\n" +
  (scenarioSummary || "- none provided");

return [{
  json: {
    ...item,
    card,
    acceptanceCriteria,
    scenarios,
    scenarioId,
    moduleName,
    category,
    group,
    shouldUseAI,
    fallbackGherkin,
    bddPrompt: prompt
  }
}];

const original = $("Preparar Prompt BDD IA").first().json;
const aiText = String($json.output || $json.content || $json.error || "").trim();

const rateLimited = /too many requests|rate limit|provider returned error|429/i.test(aiText);
const fallbackText = original.fallbackGherkin || [
  "Feature: " + (original.titulo || original.scenarioId || original.id || ""),
  "",
  "  @" + (original.scenarioId || original.id || "SEM-ID") + " @" + (original.category || "Funcional"),
  "  Scenario: " + (original.objetivo || original.titulo || original.scenarioId || original.id || ""),
  "    Given the scenario " + (original.scenarioId || original.id || "SEM-ID") + " exists",
  "    When the user processes the scenario",
  "    Then the expected outcome should be recorded"
].join("\n");

const finalGherkin = !original.shouldUseAI || rateLimited || !aiText || /^I?m sorry/i.test(aiText)
  ? fallbackText
  : aiText;

const group = String(original.group || original.grupo || original.categoria || "Funcional").trim();
const folder = /performance/i.test(group) ? "features/performance" : "features/funcionais";
const featurePath = folder + "/" + String(original.scenarioId || original.id || "sem-id").toLowerCase() + ".feature";

const owner = original.config?.githubOwner || $vars.GITHUB_OWNER || "PauloCabralGit";
const repo = original.config?.githubRepo || $vars.GITHUB_REPO || "Playwright-N8N-IA";
const branch = original.config?.githubBranch || $vars.GITHUB_BRANCH || "main";

return [{
  json: {
    ...original,
    owner,
    repo,
    branch,
    featurePath,
    gherkin: finalGherkin,
    commitMessage: "test(bdd): sync " + (original.scenarioId || original.id) + " feature file",
    aiFallbackUsed: !original.shouldUseAI || rateLimited || !aiText || /^I?m sorry/i.test(aiText)
  }
}];

return [{
  json: {
    ok: true,
    content: $json.content || "Processado com sucesso.",
    id: $json.id || "",
    featurePath: $json.featurePath || "",
    commitUrl: $json.commitUrl || ""
  }
}];

return [{
  json: {
    ok: true,
    content: $json.content || "Processado com sucesso.",
    id: $json.id || "",
    responseTarget: 'discord',
    application_id: $json.application_id || $json.interaction?.application_id || '',
    interaction_token: $json.interaction_token || $json.token || '',
    interaction_id: $json.interaction_id || $json.id || ''
  }
}];
